"""
    static func parse(_ text: String) -> [String: Double] {
        var d: [String: Double] = [:]
        for line in text.split(separator: "\n") {
            let f = line.split(separator: " ")
            if f.count == 2, let v = Double(f[1]) { d[String(f[0])] = v }
        }
        return d
    }
    static let regular: [String: Double] = parse(regularText)
    static let bold: [String: Double] = parse(boldText)
}
